import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第十四卦 大有 火天大有 离上乾下","description":"周易 - 第十四卦 大有 火天大有 离上乾下","frontmatter":{"title":"第十四卦 大有 火天大有 离上乾下","description":"周易 - 第十四卦 大有 火天大有 离上乾下"},"headers":[],"relativePath":"zh/classics/zhouyi/015.md","filePath":"zh/classics/zhouyi/015.md"}'),t={name:"zh/classics/zhouyi/015.md"};function l(s,a,n,o,c,d){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="大有" tabindex="-1">大有 <a class="header-anchor" href="#大有" aria-label="Permalink to “大有”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>元亨。 彖曰：大有，柔得尊位，大中而上下应之，曰大有。其德刚健而文明，应乎天而时行，是以元亨。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>火在天上，大有；君子以竭恶扬善，顺天休命。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>无交害，匪咎，艰则无 咎。象曰：大有初九，无交害也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>大车以载，有攸往，无咎。象曰：大车以载，积中不败也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>公用亨于天子，小人弗克。象曰：公用亨于天子，小人害也。九四：匪其彭，无咎。象曰：匪其彭，无咎；明辨晰也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>厥孚交如，威如；吉。象曰：厥孚交如，信以发志也。威如之吉，易而无备也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>自天佑之，吉无不利。象曰：大有上吉，自天佑也。</p>',15)])])}const f=e(t,[["render",l]]);export{_ as __pageData,f as default};
